-- Phase 15a (Section 55): seed real, researched compliance-control reference
-- data -- see docs/compliance-mapping.md for the sources consulted and the
-- honest-assessment methodology. Seeded directly in this migration (not an
-- app-level command) since this is reference content describing the product's
-- own capabilities -- identical for every tenant -- rather than tenant-specific
-- configuration; every tenant (present and future) gets it automatically via
-- `prisma migrate deploy`, the same mechanism every other migration already uses.

INSERT INTO "compliance_frameworks" ("id", "name", "version") VALUES ('7fe2adae-c449-5653-868e-b2360acb1266', 'ISO/IEC 27001', '2022');
INSERT INTO "compliance_frameworks" ("id", "name", "version") VALUES ('dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'NIST AI RMF', '1.0 (NIST.AI.100-1)');

INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('acf5c24a-6e94-573b-a54e-b79dcc784164', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.15', 'Access control', 'Rules to control physical and logical access to information and other associated assets shall be established and implemented based on business and information security requirements.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('f7f0942e-48a1-56b5-8691-d8c9e0a63479', 'acf5c24a-6e94-573b-a54e-b79dcc784164', 'MAPPED', 'OpenFGA task-scoped authorization ("can_use" relationship tuples per task/tool/action/resource, written by TaskGrantSyncService) is the enforcement substrate for every agent action; PolicyEngine layers deterministic, versioned, org-defined restrictions on top of an already-permitted action. See docs/authorization-model.md and docs/policy-model.md.', 'docs/authorization-model.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('372af81c-8e14-5c73-8079-d5345cd45ce8', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.16', 'Identity management', 'The full life cycle of identities shall be managed.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('d586d0d5-aa46-549f-a41e-9c6cc4ce571a', '372af81c-8e14-5c73-8079-d5345cd45ce8', 'MAPPED', 'Every agent is an independent security principal enrolled with an X.509 certificate bound to a SPIFFE-like agent://<tenantSlug>/<slug> identifier (revocable via CertificateAuthorityService.revoke); every human is a Keycloak-authenticated UserProfile, found-or-created and role-synced by JwtAuthGuard on every request. See docs/agent-identity.md and docs/human-auth.md.', 'docs/agent-identity.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('e266fba4-a856-5d28-a200-849dc8a0f398', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.17', 'Authentication information', 'Allocation and management of authentication information shall be controlled by a management process, including advising personnel on the appropriate handling of authentication information.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('29be8886-6bdb-5a44-ad29-ea7361292f66', 'e266fba4-a856-5d28-a200-849dc8a0f398', 'MAPPED', 'Tool credentials are never embedded in application code; CredentialBrokerService resolves them at invocation time through a pluggable SecretProvider (env var or OpenBao KV v2) and holds the resolved value only for the duration of the outbound call. test/tool-gateway.e2e-spec.ts proves the credential never appears in the HTTP response, any log line, or the stored ToolInvocation row. See docs/tool-gateway.md.', 'docs/tool-gateway.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('2e5eaec3-70d5-57dc-b33b-4987b3ec4993', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.18', 'Access rights', 'Access rights to information and other associated assets shall be provisioned, reviewed, modified and removed in accordance with the organization''s topic-specific policy on and rules for access control.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('08fe5169-b16a-557f-ad99-ceb647252b84', '2e5eaec3-70d5-57dc-b33b-4987b3ec4993', 'MAPPED', 'A Task''s allowedToolActions/allowedResourceSelectors/forbiddenActions are the only way an agent acquires authority; grants expire (expiresAt) and revocation (POST /tasks/:id/revoke) is enforced immediately against the live ancestor chain on every authorization check, never by a delayed background cascade. See docs/task-delegation.md and docs/authorization-model.md.', 'docs/task-delegation.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('e14c8e20-bd87-59bf-b7d3-3d2f85b0b3f8', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.8.2', 'Privileged access rights', 'The allocation and use of privileged access rights shall be restricted and managed.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('ccd2e063-b56f-5aec-8e4a-a902e8878fb4', 'e14c8e20-bd87-59bf-b7d3-3d2f85b0b3f8', 'PARTIALLY_IMPLEMENTED', 'Role-based endpoint gating (RolesGuard/@RequireRole) restricts privileged operations, and POST /users/:id/role-bindings enforces a dedicated privilege-escalation guard (src/auth/role-privilege.ts): a caller can never grant or revoke a role more privileged than any role they themselves currently hold. There is no formal periodic privileged-access review workflow yet.', 'docs/authorization-model.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('ad4a1566-65c8-5650-9c25-912895208006', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.8.5', 'Secure authentication', 'Secure authentication technologies and procedures shall be implemented based on information access restrictions and the topic-specific policy on access control.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('1beaf97b-0395-53de-bce2-2a98b6d79a80', 'ad4a1566-65c8-5650-9c25-912895208006', 'MAPPED', 'Agents authenticate exclusively via mutual TLS with certificates issued by a dedicated internal CA (AgentMtlsGuard, checked on every request, not just at handshake); humans authenticate via Keycloak-issued, signature-and-issuer-validated JWTs (JwtAuthGuard). See docs/agent-identity.md and docs/human-auth.md.', 'docs/human-auth.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('f13b687b-1d06-5d04-8c59-e293fa4e1c9b', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.8.15', 'Logging', 'Logs that record activities, exceptions, faults and other relevant events shall be produced, stored, protected and analysed.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('c8623373-1116-53f2-89fc-e33b2c3fd560', 'f13b687b-1d06-5d04-8c59-e293fa4e1c9b', 'MAPPED', 'Every authorization decision, tool invocation, approval, policy publish, and role change is recorded as an AuditEvent in a cryptographically hash-chained, append-only log (AuditService.record); verifyAuditChain detects and precisely localizes any tampering. See docs/audit-chain.md.', 'docs/audit-chain.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('69092d00-d8bf-5627-9639-73015613c2d0', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.8.16', 'Monitoring activities', 'Networks, systems and applications shall be monitored for anomalous behaviour and appropriate actions taken to evaluate potential information security incidents.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('fb4a8244-30eb-5720-ab95-49458a2ea0f8', '69092d00-d8bf-5627-9639-73015613c2d0', 'EVIDENCE_AVAILABLE', 'Every audit event is indexed into OpenSearch (AuditIndexerService) for search (GET /audit) and streamed live over Server-Sent Events (GET /events/live); there is no dedicated alerting/anomaly-detection layer on top of this data yet. See docs/audit-chain.md.', 'docs/audit-chain.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('f2191283-9ad6-58f5-b23e-e7641fc1d145', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.8.24', 'Use of cryptography', 'Rules for the effective use of cryptography, including cryptographic key management, shall be defined and implemented.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('017aede5-fc73-5174-9208-7cd4ad576e2a', 'f2191283-9ad6-58f5-b23e-e7641fc1d145', 'MAPPED', 'SHA-256 canonical-JSON hashing chains every audit event; evidence export bundles (POST /evidence/export) are HS256-signed; agent workload identity and mTLS rely on OpenBao-issued X.509 certificates. See docs/audit-chain.md and docs/agent-identity.md.', 'docs/audit-chain.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('390913a9-6b72-59f4-a3f9-a2344b45247d', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.24', 'Information security incident management planning and preparation', 'The organization shall plan and prepare for managing information security incidents by defining, establishing and communicating information security incident management processes, roles and responsibilities.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('48d488bf-fafa-5988-8360-313d6cea1989', '390913a9-6b72-59f4-a3f9-a2344b45247d', 'PARTIALLY_IMPLEMENTED', 'This phase adds a first-class Incident model (title/description/severity/status lifecycle, linkage to audit evidence via relatedCorrelationIds) with a full CRUD API and audit trail on every create/status-change -- real operational tooling, but there is no separately documented, organization-level written incident-response plan/playbook in this repository. See docs/data-classification.md.', NULL, TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('14ee7122-cd9f-56e2-885e-6b7310556486', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.26', 'Response to information security incidents', 'Information security incidents shall be responded to in accordance with the documented procedures.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('76256008-0668-5a4b-9181-d170a5499f4f', '14ee7122-cd9f-56e2-885e-6b7310556486', 'PARTIALLY_IMPLEMENTED', 'Incident.status transitions (OPEN -> INVESTIGATING -> RESOLVED -> CLOSED) are tracked and every create/status-change is audited; kill switches (src/kill-switches/) give an immediate technical containment mechanism at the tenant/agent-group/agent/tool scope. There is no automated incident-response orchestration or playbook execution engine. See docs/kill-switches.md.', 'docs/kill-switches.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('62b2751f-f5f2-52f2-92ee-b2cdaf9ec7c8', '7fe2adae-c449-5653-868e-b2360acb1266', 'A.5.28', 'Collection of evidence', 'The organization shall establish and implement procedures for the identification, collection, acquisition and preservation of evidence related to information security events.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('3b76af39-7093-518e-8bc6-33b674d80f04', '62b2751f-f5f2-52f2-92ee-b2cdaf9ec7c8', 'MAPPED', 'POST /evidence/export produces a signed JSON bundle of audit events (time/correlation/agent/task-filtered) plus their referenced context rows (Agent, Task, PolicyVersion, ApprovalRequest/Decision), independently re-verifiable via the same public hash formula the live chain uses -- any tampering after export is detectable. See docs/audit-chain.md''s evidence export section.', 'docs/audit-chain.md', TIMESTAMP '2026-08-19 00:00:00');

INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('6cd40ee7-1378-5c42-9d4e-f44a0a9a3854', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'GOVERN 1.4', 'Transparent risk management policies and controls', 'The risk management process and its outcomes are established through transparent policies, procedures, and other controls based on organizational risk priorities.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('11deb3f4-8c43-566f-b659-218ca2b525fd', '6cd40ee7-1378-5c42-9d4e-f44a0a9a3854', 'EVIDENCE_AVAILABLE', 'PolicyEngine''s declarative rule schema and RiskEngine''s deterministic 0-100 scoring formula are fully documented end to end, and every risk contributor is recorded in a response''s reasonCodes so a decision is always explainable from the API response alone. There is no separate, formally published organizational AI-risk-management policy document beyond this repository''s own docs. See docs/policy-model.md.', 'docs/policy-model.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('f2ced221-b4f8-568d-869d-36e3c8c76358', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'GOVERN 6.1', 'Policies addressing third-party AI risk', 'Policies and procedures are in place that address AI risks associated with third-party entities, including risks of infringement of a third party''s intellectual property or other rights.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('3f769f27-d73e-54ac-b471-c7e2e2e187b0', 'f2ced221-b4f8-568d-869d-36e3c8c76358', 'PARTIALLY_IMPLEMENTED', 'Tenant.allowExternalAi is a real, enforced data-residency gate on every call to an external AI provider (AiAdvisoryClient.residencyAllows), extended this phase with an independent, per-action override that blocks a RESTRICTED-classified action''s data from reaching an external provider regardless of that flag. This is one concrete technical control, not a documented third-party AI vendor risk-assessment program (contractual terms, vendor due diligence, etc.). See docs/data-classification.md.', 'docs/data-classification.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('1a14ecaa-ee89-545f-aef5-361483f53c84', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'MAP 3.5', 'Human oversight processes', 'Processes for human oversight are defined, assessed, and documented in accordance with organizational policies from the GOVERN function.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('97ddb0be-474b-5361-8d2a-934056e46657', '1a14ecaa-ee89-545f-aef5-361483f53c84', 'MAPPED', 'REQUIRE_APPROVAL is a first-class pipeline outcome that blocks tool execution until a human decides (ApprovalWorkflow); an AI-derived risk signal (AiAdvisoryClient.analyzeRisk) can only ever raise a request''s score into this human-in-the-loop path, never lower it or silently approve one -- finalRiskScore = max(deterministicRiskScore, aiAdvisoryScore ?? 0). See docs/approvals.md and docs/policy-model.md.', 'docs/approvals.md', TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('0ccd7f45-4da4-5e1d-9543-a6267fb2b9c3', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'MEASURE 2.4', 'Production monitoring of AI system behavior', 'The functionality and behavior of the AI system and its components as identified in the MAP function are monitored when in production.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('b4b24276-1c39-57fb-9392-f78ac7cd8d10', '0ccd7f45-4da4-5e1d-9543-a6267fb2b9c3', 'EVIDENCE_AVAILABLE', 'AiAdvisoryClient tracks consecutive RPC failures and opens a circuit breaker on a sustained outage, and every AI-derived score/signal/DLP finding is recorded in the audit trail -- but there is no dedicated AI-performance/drift dashboard beyond the audit log and circuit-breaker state itself.', NULL, TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('e58a9342-1d72-5b25-8571-9650e83ac460', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'MANAGE 3.1', 'Monitoring of third-party AI risk', 'AI risks and benefits from third-party resources are regularly monitored, and risk controls are applied and documented.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('741b2d8d-265c-5b33-a463-a8ba6ec1330d', 'e58a9342-1d72-5b25-8571-9650e83ac460', 'PARTIALLY_IMPLEMENTED', 'The circuit breaker (default: 3 consecutive failures / 30s cooldown) is a real, tested automatic response to a degraded or unreachable manar-ai backend, and every failure is logged server-side -- but there is no formal periodic third-party AI risk register or contractual risk-monitoring process.', NULL, TIMESTAMP '2026-08-19 00:00:00');
INSERT INTO "compliance_controls" ("id", "frameworkId", "controlId", "title", "description") VALUES ('13e34ab7-0220-5408-84b8-52bab779ed8b', 'dfbfb697-4630-5dc2-98fc-eb60721f29c6', 'MANAGE 4.1', 'Post-deployment AI monitoring and incident response', 'Post-deployment AI system monitoring plans are implemented, including mechanisms for capturing and evaluating input from users and other relevant AI actors, appeal and override, decommissioning, incident response, recovery, and change management.');
INSERT INTO "compliance_mappings" ("id", "controlId", "status", "evidenceDescription", "evidenceReference", "assessedAt") VALUES ('f8fb9dc7-2b08-59fc-be2f-c87bba2b009b', '13e34ab7-0220-5408-84b8-52bab779ed8b', 'PARTIALLY_IMPLEMENTED', 'This phase''s Incident model plus the existing audit chain, evidence export, and kill-switch machinery cover the incident-response/recovery primitives this control calls for; there is no dedicated, separately-scheduled post-deployment AI monitoring plan artifact beyond the always-on circuit breaker and audit trail. See docs/kill-switches.md.', 'docs/kill-switches.md', TIMESTAMP '2026-08-19 00:00:00');
